const query = $('WEBHOOK GET VERIFICACAO').first().json.query ?? $input.first().json.query ?? $input.first().json;
const config = $('CONFIG API OFICIAL').first().json;
const verifyToken = config.verify_token || config.verifyToken;

if (!verifyToken) {
  throw new Error('Configure verify_token em SAAS_Config_ApiOficial.');
}

const mode = query['hub.mode'] || query.hub?.mode;
const token = query['hub.verify_token'] || query.hub?.verify_token;
const challenge = query['hub.challenge'] || query.hub?.challenge;

if (mode === 'subscribe' && token === verifyToken && challenge) {
  return [{ json: { challenge: String(challenge), verified: true } }];
}

return [{ json: { verified: false } }];

const raw = $input.first().json;
const body = raw.body ?? raw;

const entries = Array.isArray(body.entry) ? body.entry : [];
const events = [];

for (const entry of entries) {
  const wabaId = entry.id;
  const changes = Array.isArray(entry.changes) ? entry.changes : [];
  for (const change of changes) {
    events.push({
      waba_id: wabaId,
      field: change.field,
      value: change.value,
      received_at: new Date().toISOString()
    });
  }
}

return events.length
  ? events.map((event) => ({ json: { ...event, empty: false } }))
  : [{ json: { empty: true, received_at: new Date().toISOString() } }];

const mediaTypes = ['image', 'audio', 'video', 'document', 'sticker'];
const extMap = {
  'image/jpeg': 'jpg',
  'image/jpg': 'jpg',
  'image/png': 'png',
  'image/webp': 'webp',
  'video/mp4': 'mp4',
  'video/3gpp': '3gp',
  'audio/ogg': 'ogg',
  'audio/ogg; codecs=opus': 'ogg',
  'audio/mpeg': 'mp3',
  'audio/aac': 'aac',
  'application/pdf': 'pdf'
};
const out = [];

for (const item of $input.all()) {
  const e = item.json;
  if (e.empty || e.field !== 'messages') continue;

  const value = e.value || {};
  const phoneNumberId = value.metadata?.phone_number_id || null;
  const contacts = Array.isArray(value.contacts) ? value.contacts : [];
  const nomeContato = contacts[0]?.profile?.name || null;
  const messages = Array.isArray(value.messages) ? value.messages : [];

  for (const msg of messages) {
    const type = msg.type;
    if (!mediaTypes.includes(type)) continue;

    const block = msg[type] || {};
    const mediaId = block.id;
    if (!mediaId) continue;

    let ext = extMap[(block.mime_type || '').toLowerCase()] || 'bin';
    if (block.filename && String(block.filename).includes('.')) {
      ext = String(block.filename).split('.').pop() || ext;
    }

    const safeId = String(msg.id || mediaId).replace(/[^a-zA-Z0-9._-]/g, '_');

    out.push({
      json: {
        waba_id: e.waba_id,
        phone_number_id: phoneNumberId,
        meta_message_id: msg.id,
        telefone: msg.from,
        tipo_mensagem: type,
        mensagem: block.caption || null,
        media_id: mediaId,
        mime_type: block.mime_type || null,
        filename_meta: block.filename || null,
        nome_contato: nomeContato,
        received_at: e.received_at,
        file_ext: ext,
        safe_message_id: safeId,
        mensagemRespondida: msg.context?.id || null
      }
    });
  }
}

return out;
